"""Fixed whole-source controls; actual Slot76 execution remains a separate gate."""
from __future__ import annotations
import ast
import base64
from collections import Counter
import gzip
from hashlib import sha256
import json
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

from tests import hia_slot_integration_component_history as history

ROOT = Path(__file__).resolve().parents[1]
PREDECESSORS_SHA256 = "ee8fc24ab229c5f867cc1142128713fb4faf7601151b2c7ecf6bab093225b5b9"
PREDECESSORS_BASE64 = ""
INSTALLED_METHOD = "test_installed_sdist_wheel_uses_packaged_slot_owner_for_actual_service_and_refuses_source_drift"


class SlotIntegrationComponentHistoryTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        packed = base64.b64decode(PREDECESSORS_BASE64, validate=True)
        if sha256(packed).hexdigest() != PREDECESSORS_SHA256:
            raise AssertionError("independently captured predecessor corpus changed")
        values = json.loads(gzip.decompress(packed))
        cls.versions = {name: base64.b64decode(raw, validate=True) for name, raw in values.items()}
        cls.current = (ROOT / history.PATH).read_bytes()
        cls.frozen = (ROOT / history.FIXTURE).read_bytes()
        cls.versions["current"] = cls.current
        if set(cls.versions) != set(history.VERSIONS):
            raise AssertionError("complete source version set differs")
        for name, raw in cls.versions.items():
            if history.pin(raw) != history.VERSIONS[name]:
                raise AssertionError("independently captured full source differs: " + name)

    def copy_inputs(self, folder):
        root = Path(folder).resolve()
        names = (history.PATH, history.FIXTURE, history.LEGACY_FIXTURE,
                 history.COLD_INPUT_SOURCE, *history.COMPONENT_PINS)
        for name in names:
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes((ROOT / name).read_bytes())
        return root, names

    def test_fixed_full_chain_replays_every_independent_predecessor(self):
        restored, proof = history.reviewed(history.PATH, self.current, root=ROOT)
        self.assertEqual(restored, self.versions["installed"])
        self.assertIs(proof["all_three_complete_relations_reversed_and_replayed"], True)
        self.assertIs(proof["native_cold_qualified"], False)
        self.assertIs(proof["whole_native_delivery_qualified"], False)
        fixture = json.loads(self.frozen)
        value = self.current
        for relation, old, new in (
                ("current_to_external", "external", "current"),
                ("external_to_installed", "installed", "external"),
                ("installed_to_original", "original", "installed")):
            value = history._inverse(value, fixture["relations"][relation],
                                     history.VERSIONS[old], history.VERSIONS[new])
            self.assertEqual(value, self.versions[old])
        self.assertEqual(history.predecessor(history.PATH, self.current, root=ROOT),
                         self.versions["installed"])

    def test_unknown_versions_gain_no_history_authority(self):
        for raw in (b"", self.current + b"\n# unknown\n", *(
                self.versions[name] for name in ("external", "installed", "original"))):
            self.assertEqual(history.reviewed(history.PATH, raw, root=ROOT), (raw, None))
        self.assertEqual(history.reviewed("unknown", self.current, root=ROOT), (self.current, None))
        with self.assertRaisesRegex(ValueError, "exact bytes"):
            history.reviewed(history.PATH, self.current.decode(), root=ROOT)

    def test_original_methods_assertions_and_embedded_product_script_remain(self):
        original = ast.parse(self.versions["original"])
        current = ast.parse(self.current)
        allowed = {"source_map", "setUpClass", "finish_custody", INSTALLED_METHOD}
        def methods(tree):
            return {node.name: ast.dump(node, include_attributes=False) for node in ast.walk(tree)
                    if isinstance(node, ast.FunctionDef) and node.name not in allowed}
        self.assertEqual(methods(original), methods(current))
        def assertions(tree):
            return Counter(ast.dump(node, include_attributes=False) for node in ast.walk(tree)
                           if isinstance(node, ast.Assert)
                           or isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                           and node.func.attr.startswith("assert"))
        self.assertFalse(assertions(original) - assertions(current))
        def product_script(tree):
            method = next(n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)
                          and n.name == INSTALLED_METHOD)
            return next(ast.dump(n.value, include_attributes=False) for n in method.body
                        if isinstance(n, ast.Assign) and isinstance(n.targets[0], ast.Name)
                        and n.targets[0].id == "script")
        self.assertEqual(product_script(original), product_script(current))
        def identities(tree):
            return next(ast.literal_eval(n.value) for n in tree.body
                        if isinstance(n, ast.Assign) and isinstance(n.targets[0], ast.Name)
                        and n.targets[0].id == "ORIGINAL_IDS")
        self.assertEqual(identities(original), identities(current))
        self.assertEqual(len(identities(current)), 10)

    def test_all_original_budgets_and_strict_combined_wheel_bound_remain(self):
        original = ast.parse(self.versions["original"])
        current = ast.parse(self.current)
        def calls(tree):
            return {node.args[0].value: node for node in ast.walk(tree)
                    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "run_recorded" and node.args
                    and isinstance(node.args[0], ast.Constant)}
        before, after = calls(original), calls(current)
        self.assertEqual(set(before), set(after))
        for name in before:
            def timeout(call):
                return next(node.value for node in call.keywords if node.arg == "timeout")
            if name != "wheel":
                self.assertEqual(ast.dump(timeout(before[name]), include_attributes=False),
                                 ast.dump(timeout(after[name]), include_attributes=False), name)
            else:
                self.assertEqual(ast.literal_eval(timeout(before[name])), 90)
                self.assertIsInstance(timeout(after[name]), ast.Name)
                self.assertEqual(timeout(after[name]).id, "wheel_remaining")
        assignments = {node.targets[0].id: node.value for node in ast.walk(current)
                       if isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Name)}
        self.assertEqual(ast.dump(assignments["wheel_remaining"], include_attributes=False),
                         ast.dump(ast.parse("90 - component_seconds", mode="eval").body,
                                  include_attributes=False))
        self.assertIn(b"self.assertLessEqual(wheel_seconds, 90,", self.current)
        self.assertNotIn(b"timeout=1800", self.current)
        self.assertIn(b"cls.bindings.update(cold_inputs.files)", self.current)
        self.assertIn(b"cls.cold_inputs.unchanged()", self.current)
        self.assertIn(b"terminal_cold.files != cls.cold_inputs.files", self.current)
        self.assertEqual(self.current.count(b"verify_component_install(component, installed, installed_from=wheel)"), 2)

    def test_every_input_uses_explicit_root_and_terminal_capture(self):
        with tempfile.TemporaryDirectory(prefix="hia-slot-install-history-root-") as folder:
            root, names = self.copy_inputs(folder)
            captures = []
            def take(path):
                self.assertTrue(path.is_relative_to(root))
                captures.append(path.relative_to(root).as_posix())
                return path.read_bytes()
            with patch.object(history, "ROOT", root / "must-not-read"):
                prior, proof = history.reviewed(history.PATH, self.current, root=root, take=take)
            self.assertEqual(prior, self.versions["installed"])
            self.assertEqual(Counter(captures), Counter({name: 2 for name in names}))
            self.assertEqual(set(proof["captured_inputs"]), set(names))

    def test_late_physical_mutation_of_every_capture_is_refused(self):
        with tempfile.TemporaryDirectory(prefix="hia-slot-install-history-late-") as folder:
            root, names = self.copy_inputs(folder)
            for name in names:
                target = root / name
                before = target.read_bytes()
                changed = False
                def take(path):
                    nonlocal changed
                    raw = path.read_bytes()
                    if path == target and not changed:
                        path.write_bytes(raw + b"\n# late physical change\n")
                        changed = True
                    return raw
                try:
                    with self.subTest(path=name), self.assertRaisesRegex(ValueError, "during review"):
                        history.reviewed(history.PATH, self.current, root=root, take=take)
                    self.assertTrue(changed)
                finally:
                    target.write_bytes(before)

    def test_fixed_pins_splices_and_numeric_types_refuse_rebinding(self):
        with tempfile.TemporaryDirectory(prefix="hia-slot-install-history-fixture-") as folder:
            root, _ = self.copy_inputs(folder)
            fixture = root / history.FIXTURE
            mutations = (
                ("scope-int", lambda v: v.__setitem__("whole_native_delivery_qualified", 0)),
                ("budget-float", lambda v: v.__setitem__("original_wheel_budget_seconds", 90.0)),
                ("old-budget", lambda v: v.__setitem__("superseded_wheel_budget_seconds", 90)),
                ("version-float", lambda v: v["versions"]["original"].__setitem__(
                    "bytes", float(v["versions"]["original"]["bytes"]))),
                ("missing-relation", lambda v: v["relations"].pop("external_to_installed")),
                ("bool-offset", lambda v: v["relations"]["current_to_external"]["hunks"][0].__setitem__("old_offset", True)),
                ("changed-splice", lambda v: v["relations"]["external_to_installed"]["hunks"][0].__setitem__("old_hex", "00")),
                ("wrong-pin", lambda v: v["relations"]["installed_to_original"]["old"].__setitem__("sha256", "0" * 64)),
                ("wrong-external-object", lambda v: v.__setitem__("external_source_blob", "0" * 40)),
            )
            fixture.write_bytes(self.frozen + b" ")
            with self.assertRaisesRegex(ValueError, "immutable"):
                history.reviewed(history.PATH, self.current, root=root)
            for label, change in mutations:
                value = json.loads(self.frozen)
                change(value)
                raw = (json.dumps(value, sort_keys=True) + "\n").encode()
                fixture.write_bytes(raw)
                with self.subTest(label=label), patch.object(history, "FIXTURE_SHA256", sha256(raw).hexdigest()):
                    with self.assertRaises(ValueError):
                        history.reviewed(history.PATH, self.current, root=root)
            duplicate = b'{"schema":"duplicate",' + self.frozen.lstrip()[1:]
            fixture.write_bytes(duplicate)
            with patch.object(history, "FIXTURE_SHA256", sha256(duplicate).hexdigest()):
                with self.assertRaisesRegex(ValueError, "duplicate"):
                    history.reviewed(history.PATH, self.current, root=root)

    def test_partial_wrong_or_missing_current_inputs_are_refused(self):
        with tempfile.TemporaryDirectory(prefix="hia-slot-install-history-input-") as folder:
            root, names = self.copy_inputs(folder)
            for name in names:
                path = root / name
                before = path.read_bytes()
                path.unlink()
                try:
                    with self.subTest(missing=name), self.assertRaisesRegex(ValueError, "missing captured"):
                        history.reviewed(history.PATH, self.current, root=root)
                finally:
                    path.write_bytes(before)
            path = root / history.PATH
            path.write_bytes(self.versions["external"])
            with self.assertRaisesRegex(ValueError, "provided source"):
                history.reviewed(history.PATH, self.current, root=root)
            path.write_bytes(self.current)
            for name in history.COMPONENT_PINS:
                path = root / name
                before = path.read_bytes()
                path.write_bytes(before + b"\n# changed component\n")
                try:
                    with self.assertRaisesRegex(ValueError, "component source"):
                        history.reviewed(history.PATH, self.current, root=root)
                finally:
                    path.write_bytes(before)


if __name__ == "__main__":
    unittest.main(verbosity=2)
